SELECT MIN(i.price) FROM t_item i WHERE i.deleted = 0 AND i.status = 'ON_SALE'
AND i.category_id = #{categoryId}
AND i.title LIKE CONCAT('%', #{keyword}, '%')

SELECT i.* FROM t_item i WHERE i.deleted = 0
AND i.status = #{q.status}
AND i.risk_level = #{q.riskLevel}
AND i.category_id = #{q.categoryId}
AND i.school_id = #{q.schoolId}
AND (i.title LIKE CONCAT('%', #{q.keyword}, '%') OR i.description LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY CASE i.risk_level WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END ASC, i.created_at DESC, i.id DESC
ORDER BY i.created_at DESC, i.id DESC
